<?php require_once APP_ROOT.'/lib/mod_logs.php';$sources=log_sources(); ?>
<div class="page-header"><div><h1 class="page-title">Logs</h1><p class="page-subtitle">Centralized log viewer across services</p></div><div class="page-actions"><button class="btn btn-secondary" type="button" id="logDownload"><i data-lucide="download"></i>Download view</button></div></div>
<?php if(!$sources): ?><?= requirement_missing('scroll-text', 'No log sources available', 'No managed service journals or readable files under <span class="mono">/var/log</span> were found.') ?><?php else: ?>
<div class="log-layout"><?php $logIcons=['nginx'=>'server-cog','apache2'=>'server','mariadb'=>'database','mysql'=>'database','redis-server'=>'zap','docker'=>'container','ssh'=>'key-round','cron'=>'clock','ufw'=>'shield']; ?>
<aside class="card log-sources" aria-label="Log sources"><?php foreach($sources as $i=>$source): $unit=str_starts_with($source['id'],'unit:')?substr($source['id'],5):''; ?><button type="button" class="log-source<?= $i===0?' active':'' ?>" aria-pressed="<?= $i===0?'true':'false' ?>" data-log-source="<?= e($source['id']) ?>" title="<?= e($source['detail'] ?? $source['label']) ?>"><i data-lucide="<?= e($unit!=='' ? ($logIcons[$unit] ?? (str_starts_with($unit,'php')?'code-2':'server')) : 'file-text') ?>"></i><span class="log-source-text"><span><?= e($source['label']) ?></span><small><?= e($source['detail'] ?? '') ?></small></span></button><?php endforeach; ?></aside>
<section class="log-main"><div class="log-toolbar"><div class="log-search"><i data-lucide="search" aria-hidden="true"></i><input id="logSearch" type="search" placeholder="Filter log lines…" aria-label="Filter log lines"></div><div class="flex gap-1" role="group" aria-label="Severity"><button type="button" class="chip active" aria-pressed="true" data-log-level="all">All</button><button type="button" class="chip" aria-pressed="false" data-log-level="warning">Warnings</button><button type="button" class="chip" aria-pressed="false" data-log-level="error">Errors</button></div><div class="topbar-spacer"></div><select class="select input-sm" id="logLines" aria-label="Lines to load" style="width:auto"><option value="100">100 lines</option><option value="200" selected>200 lines</option><option value="500">500 lines</option><option value="1000">1,000 lines</option></select><button class="btn btn-secondary btn-sm" type="button" id="logLive" aria-pressed="false"><i data-lucide="pause"></i><span>Pause</span></button><button class="btn btn-secondary btn-sm" type="button" id="logRefresh"><i data-lucide="refresh-cw"></i>Refresh</button></div>
<div class="term-window log-window"><div class="term-titlebar"><i data-lucide="scroll-text" aria-hidden="true"></i><span id="logTitle"></span><span class="topbar-spacer"></span><span class="live-badge" id="logLiveBadge"><span class="live-dot"></span>live tail</span></div><pre class="term-body" id="logOutput" tabindex="0" aria-label="Log output" aria-live="off">Loading…</pre></div>
<div class="log-stats"><div class="log-stat"><div class="lv" id="logErrors">0</div><div class="ll">Errors in view</div></div><div class="log-stat"><div class="lv" id="logWarnings">0</div><div class="ll">Warnings in view</div></div><div class="log-stat"><div class="lv" id="logVisible">0</div><div class="ll">Visible lines</div></div><div class="log-stat"><div class="lv" id="logTotal">0</div><div class="ll">Loaded lines</div></div></div></section></div>
<script>document.addEventListener('DOMContentLoaded',()=>{let raw='',paused=false,level='all';const out=document.getElementById('logOutput'),search=document.getElementById('logSearch');const activeSource=()=>document.querySelector('[data-log-source].active');function render(){const q=search.value.toLowerCase();let lines=raw.split(/\r?\n/).filter(Boolean);const errors=lines.filter(l=>/\berror\b|\bfatal\b|\bcrit/i.test(l)).length,warnings=lines.filter(l=>/\bwarn(?:ing)?\b/i.test(l)).length;const filtered=lines.filter(l=>(!q||l.toLowerCase().includes(q))&&(level==='all'||(level==='error'?/\berror\b|\bfatal\b|\bcrit/i.test(l):/\bwarn(?:ing)?\b/i.test(l))));out.textContent=filtered.join('\n')||'(no matching lines)';const errEl=document.getElementById('logErrors'),warnEl=document.getElementById('logWarnings');errEl.textContent=errors;warnEl.textContent=warnings;errEl.classList.toggle('text-red',errors>0);warnEl.classList.toggle('text-orange',warnings>0);document.getElementById('logVisible').textContent=filtered.length;document.getElementById('logTotal').textContent=lines.length;if(!paused)out.scrollTop=out.scrollHeight;}async function load(){const src=activeSource();if(!src)return;document.getElementById('logTitle').textContent=src.title||src.textContent.trim();try{const r=await fetch(window.Nebula.api('logs')+'&source='+encodeURIComponent(src.dataset.logSource)+'&lines='+document.getElementById('logLines').value),d=await r.json();raw=d.text||'';render();}catch(e){window.Nebula.toast('Failed to load log','error');}}document.querySelectorAll('[data-log-source]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-log-source]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b?'true':'false');});load();});document.querySelectorAll('[data-log-level]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-log-level]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b?'true':'false');});level=b.dataset.logLevel;render();});search.oninput=render;document.getElementById('logLines').onchange=load;document.getElementById('logRefresh').onclick=load;document.getElementById('logLive').onclick=()=>{paused=!paused;const live=document.getElementById('logLive');live.querySelector('span').textContent=paused?'Resume':'Pause';live.setAttribute('aria-pressed',paused?'true':'false');const ico=document.createElement('i');ico.setAttribute('data-lucide',paused?'play':'pause');live.querySelector('svg,i')?.replaceWith(ico);if(window.lucide)lucide.createIcons();document.getElementById('logLiveBadge').lastChild.textContent=paused?'paused':'live tail';document.getElementById('logLiveBadge').classList.toggle('paused',paused);};document.getElementById('logDownload').onclick=()=>{const blob=new Blob([out.textContent],{type:'text/plain'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='nebula-log-'+new Date().toISOString().slice(0,10)+'.log';a.click();URL.revokeObjectURL(a.href);};load();setInterval(()=>{if(!paused)load();},5000);});</script>
<script>document.addEventListener('DOMContentLoaded',()=>{let autoPaused=false;document.addEventListener('visibilitychange',()=>{const button=document.getElementById('logLive'),label=button?.querySelector('span');if(!button||!label)return;if(document.hidden&&label.textContent==='Pause'){autoPaused=true;button.click();}else if(!document.hidden&&autoPaused&&label.textContent==='Resume'){autoPaused=false;button.click();}});});</script>
<?php endif; ?>
